import { Injectable } from '@angular/core';
import pdfMake from 'pdfmake/build/pdfmake';
import pdfFonts from 'pdfmake/build/vfs_fonts';
import { Ami, Tenderer } from 'src/app/marchepublic/shared/models/ami';
pdfMake.vfs = pdfFonts.pdfMake.vfs;

@Injectable({
  providedIn: 'root',
})
export class PdfService {
  constructor() { }

  generateDirectoryReport(ami: Ami, tenderers: Tenderer[]) {
    let title = `\nListes des soumissionaire enregistré dans le répertoire\n\n`;
    let dd = this.reportSkeleton();

    dd.content.push({
      canvas: [
        { type: 'line', x1: 0, y1: 5, x2: 595 - 40, y2: 5, lineWidth: 1 },
      ],
    });

    dd.content.push({
      text: title,
      alignment: 'center',
      fontSize: 15,
      bold: true,
    });
    let directoryTable: {
      alignment: string;
      margin: any;
      widths: any;
      heights: any;
      dontBreakRows: any;
      headerRows: any;
      body: Array<Array<any>>;
    } = {
      alignment: 'left',
      margin: 20,
      widths: [
        12,
        80,
        40,
        45,
        50,
        50,
        70,
        55,
        'auto',
      ],
      heights: 20,
      dontBreakRows: true,
      headerRows: 2,
      body: [
        [
          { text: 'N°', style: 'th', rowSpan: 2 },
          { text: 'Structure', style: 'th', colSpan: 8 },
          {},
          {},
          {},
          {},
          {},
          {},
          {},
        ],
        [
          {},
          { text: 'Raison sociale', style: 'th' },
          { text: 'Forme juridique', style: 'th' },
          { text: 'IFU', style: 'th' },
          { text: 'RCCM', style: 'th' },
          { text: 'Téléphone', style: 'th' },
          { text: 'Email', style: 'th' },
          { text: 'Adresse', style: 'th' },
          { text: 'Boîte postale', style: 'th' },
        ],
      ],
    };

    directoryTable.body.push(
      ...tenderers.map((tenderer, index) => {
        return [
          { text: `${index + 1}`, style: 'tr' },
          { text: `${tenderer.raisonSociale}`, style: 'tr' },
          { text: `${tenderer.formeJuridique}`, style: 'tr' },
          { text: `${tenderer.numeroIfu}`, style: 'tr' },
          { text: `${tenderer.numeroRccm}`, style: 'tr' },
          { text: `${tenderer.telephoneStructure}`, style: 'tr' },
          { text: `${tenderer.email}`, style: 'tr' },
          { text: `${tenderer.adresse}`, style: 'tr' },
          { text: `${tenderer.bp}`, style: 'tr' },
        ];
      })
    );

    // dd.pageOrientation = 'landscape';

    dd.content.push({
      table: this.singleAMITable(ami),
      layout: {},
    });

    dd.content.push('\n');

    dd.content.push({
      table: directoryTable,
      layout: {},
    });
    pdfMake.createPdf(dd).open();
    //     pdfMake.createPDF(docDefinition).open();
    // pdfMake.createPDF(docDefinition).download();
    // pdfMake.createPDF(docDefinition).print();
  }

  reportSkeleton(): any {
    return {
      pageMargins: [15, 100, 25, 50],
      header: {
        margin: 15,
        columns: [
          {
            table: {
              margin: 5,
              widths: ['*', '*'],
              body: [
                [
                  {
                    image: `data:image/jpeg;base64,`,
                    width: 104,
                    height: 60,
                  },
                  {
                    stack: [
                      {
                        text: 'REPUBLIQUE DU BENIN',
                        bold: true,
                      },
                      {
                        text: `Office National d'Imprimerie et de Presse`,
                        bold: true,
                      },
                      {
                        text: 'Servie de la Personne Responsable des Marchés Publics',
                      },

                      {
                        text: [
                          '01 BP 1210 Cotonou\n',
                          { text: 'Tél', bold: true },
                          ': (+229) 21 301 152 \n',
                          { text: 'Fax', bold: true },
                          ': (+229) 21 30 34 63 ',
                        ],
                      },
                      'www.onip.net',
                    ],
                    alignment: 'right',
                    fontSize: 9,
                    lineHeight: 1.2,
                  },
                ],
              ],
            },
            layout: 'noBorders',
          },
        ],
      },
      footer: function (currentPage, pageCount) {
        return [
          {
            margin: [30, 0, 25, 0],
            columns: [
              {
                stack: [
                  { text: ' ' },
                  {
                    text: currentPage.toString() + ' / ' + pageCount,
                    alignment: 'center',
                  },
                ],
              },
            ],
          },
        ];
      },
      content: [],
      styles: {
        th: { bold: true, fontSize: 10, color: 'black' },
        tr: { fontSize: 9 },
        trn: { fontSize: 9, alignment: 'right' },
      },
    };
  }

  directoriesTable() { }

  singleAMITable(ami: Ami) {
    return {
      margin: [60, 20],
      widths: ['auto', 'auto', 'auto', 'auto'],
      heights: 'auto',
      dontBreakRows: true,
      // headerRows: 1,
      body: [
        [
          {
            text: "Avis à manifestation d'intérêt",
            style: 'th',
            colSpan: 4,
            alignment: 'center',
          },
          {},
          {},
          {},
        ],
        [
          { text: 'Exercice', style: 'th' },
          { text: `${ami.exercice.annee}`, style: 'tr' },
          { text: 'Date de début', style: 'th' },
          { text: `${ami.dateDebut || '-'}`, style: 'tr' },
        ],
        [
          { text: 'Référence', style: 'th' },
          { text: `${ami.reference}`, style: 'tr' },
          { text: 'Date de fin', style: 'th' },
          { text: `${ami.dateFin || '-'}`, style: 'tr' },
        ],
        [
          { text: 'Référence SIGMAP', style: 'th' },
          { text: `${ami.referenceSigmap}`, style: 'tr' },
          { text: 'Date de signature', style: 'th' },
          { text: `${ami.dateSignature || '-'}`, style: 'tr' },
        ],
        [
          { text: 'Objet', style: 'th' },
          { text: `${ami.objet}`, style: 'tr' },
          { text: 'Date de publication', style: 'th' },
          { text: `${ami.datePublication || '-'}`, style: 'tr' },
        ],
      ],
    };
  }
}
